const all = queries.returns.data || [];
const order = ['Submitted', 'Inspected', 'Approved', 'Draft', 'Rejected'];
const money = n => new Intl.NumberFormat('en-US', {style: 'currency', currency: 'USD'}).format(n || 0);
const date = d => d ? new Date(d + 'T12:00:00').toLocaleDateString('en-US', {month: 'short', day: 'numeric'}) : '—';
const shape = r => {
  const items = r?.items || [];
  return {
    id: r?.id, reference: r?.reference, status: r?.status, customer: r?.customer, reason: r?.reason,
    orderLine: 'Order ' + (r?.order_reference || '—') + ' · Received ' + date(r?.received_date),
    purchased: date(r?.purchase_date), received: date(r?.received_date),
    requested: money(items.reduce((n, i) => n + (i.qty || 0) * (i.price || 0), 0)),
    approved: money(items.reduce((n, i) => n + (i.approved_qty || 0) * (i.price || 0), 0)),
    items: items.slice(0, 2).map(i => ({ name: i.name, qty: i.qty, sub: i.inspected ? (i.condition + ' · ' + i.disposition) : 'Awaiting inspection' })),
    itemsCount: items.length, refundRef: r?.refund_reference, history: (r?.history || []).slice().reverse()
  };
};
const selected = all.find(x => x.id === variables.returnId);
const fallback = selected || all.filter(x => !['Closed', 'Cancelled', 'Rejected'].includes(x.status)).sort((a, b) => order.indexOf(a.status) - order.indexOf(b.status) || String(a.received_date || '').localeCompare(String(b.received_date || '')))[0];
return { case: shape(fallback), selected: shape(selected) };
